// Firestoreに初期データを投入する関数
export const initializeSupportSystemsData = async (db) => {
  const { collection, doc, setDoc, getDoc } = await import('firebase/firestore');
  
  try {
    const supportSystemsRef = collection(db, 'supportSystems');
    let addedCount = 0;
    let errorCount = 0;
    
    console.log(`📝 ${initialSupportSystemsData.length}件の制度データを投入します...`);
    
    for (const system of initialSupportSystemsData) {
      try {
        const systemRef = doc(supportSystemsRef, String(system.id));
        
        // 既に存在する場合は更新、存在しない場合は追加
        const snapshot = await getDoc(systemRef);
        if (snapshot.exists()) {
          // 既存データを更新（特にministryNameなどの重要な情報を更新）
          await setDoc(systemRef, system, { merge: false }); // merge: falseで完全に上書き
          console.log(`🔄 制度「${system.title}」(ID: ${system.id})のデータを更新しました。`);
          addedCount++;
        } else {
          // 新規データを追加
          await setDoc(systemRef, system);
          console.log(`✅ 制度「${system.title}」(ID: ${system.id}, カテゴリ: ${system.category})を追加しました。`);
          addedCount++;
        }
      } catch (error) {
        console.error(`❌ 制度「${system.title}」(ID: ${system.id})の追加・更新に失敗しました:`, error);
        errorCount++;
      }
    }
    
    console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
    console.log(`📊 データ投入結果:`);
    console.log(`   ✅ 追加・更新: ${addedCount}件`);
    console.log(`   ❌ エラー: ${errorCount}件`);
    console.log(`   📝 合計: ${initialSupportSystemsData.length}件`);
    console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
    console.log('✅ 出産支援制度のマスターデータの投入が完了しました。');
    
    return { added: addedCount, skipped: 0, errors: errorCount };
  } catch (error) {
    console.error('❌ データ投入中にエラーが発生しました:', error);
    console.error('エラー詳細:', {
      message: error.message,
      code: error.code,
      stack: error.stack
    });
    throw error;
  }
};

